# Catch accidental gaps and templated filler during authoring, before the JSON
# is regenerated. The length limits enforce substantial but scannable notes.
assert set(EXTRAS) == set(range(1, 23))
assert sum(len(lessons) for lessons in EXTRAS.values()) == 99
assert all(90 <= len(text) <= 420 for lessons in EXTRAS.values() for pair in lessons for text in pair)
assert len({text for lessons in EXTRAS.values() for pair in lessons for text in pair}) == 198
